const PT = [36.9, -9.65, 42.2, -6.15], ROUTE = [36.95, -9.25, 41.25, -7.55], CORR = [38.85, -9.35, 39.85, -8.3], PORTO = [41.13, -8.66, 41.19, -8.55], IP3B = [40.3, -8.35, 40.8, -7.75];
