const PORTO_IN = [41.135, -8.64, 41.17, -8.565];
export const LINES = { j17: { route: RID }, d17: { route: RID, k: [0, 282] }, a17: { route: RID, k: [282, 556] }, leg: { route: RID, k: [282, 331] }, bey: { route: RID, k: [331, 556] }, last: { route: RID, k: [520, 556] }, alt: { route: "faro__porto__no_tolls" },
  vci: { geom: "vciPortoRing" }, ip3: { geom: "ip3Works2026" }, v22: { route: "viseu__faro__fastest" }, v22n: { route: "viseu__faro__no_tolls" },
  ...Object.fromEntries(Object.entries(JR).filter(([k]) => k !== "J-4217").map(([k, [r]]) => ["o" + k.slice(-2), { route: r }])) };
const OTHERS = (st) => Object.fromEntries(Object.keys(LINES).filter(k => k[0] === "o").map(k => [k, st]));
const full = { x: 0, y: 0, w: PW, h: PH };
const M = (r, cam, o = {}) => ({ ...r, cam, ...o });
const truckPin = (km = 282, extra = {}) => ({ route: RID, km, mark: "truck", ...extra });
const stopPins = (lab = true, dark = false) => STOPS.map(([k, n, t], i) => ({ route: RID, km: k, mark: i === 0 ? "start" : i === 1 ? "pause" : i === 3 ? "end" : "stop", ...(lab ? { t: n, s: t, dx: 26, dy: -10, cls: dark ? "l" : "" } : {}) }));
const top = (html, w = 900) => ({ id: "head", x: 48, y: 30, w, h: 130, html });

// bottom strip leaders: strip block at (bx,by,bw) -> stations to map positions
const stripLeaders = (bx, by, bw, P, dark = false) => STOPS.map(([k]) => { const sx = bx + 20 + (k / KM) * (bw - 40), sy = by + 40; const [mx, my] = P(ptAt(RID, k)); return `<path d="M${sx} ${sy - 8} C ${sx} ${sy - 120}, ${mx} ${my + 120}, ${mx} ${my + 10}" fill="none" stroke="${dark ? "#4f6b62" : "#a8a397"}" stroke-width="1" stroke-dasharray="3 3"/>`; }).join("");
const hourTicks = (P, dark) => [["07:00", 30], ["08:00", 118], ["09:00", 205], ["10:05", 282], ["11:17", 320], ["12:00", 380], ["12:57", 441], ["14:00", 490], ["15:12", 556]].map(([t, k]) => { const [x, y] = P(ptAt(RID, k)); return `<line x1="${x - 7}" y1="${y}" x2="${x + 7}" y2="${y}" stroke="${t === "10:05" ? "#c8551f" : dark ? "#9fd3b8" : "#141f1b"}" stroke-width="2"/>${T(x - 12, y + 4, t, { a: "end", m: 1, s: 11, w: t === "10:05" ? 700 : 500, c: t === "10:05" ? "#c8551f" : dark ? "#cfe0d9" : "#34433d" })}`; }).join("");

